  const total = Math.ceil((ml + 9) / 64) * 64;
  const buf = new Uint8Array(total);
  buf.set(msg);
  buf[ml] = 0x80;
  const dv = new DataView(buf.buffer);
  dv.setUint32(total - 4, ml * 8, false);
  dv.setUint32(total - 8, Math.floor(ml / 0x20000000), false);
